// Шапка заявления работодателю: адресат справа, заявитель ниже (мекс. делопроизводство)
const workHdr = (): TplDef['body'] => [
  { type: 'lines', align: 'right', items: ['{{org_name}}', 'A la atención de: {{head_name}}', '', 'C. {{applicant_name}}', 'RFC: {{applicant_rfc}}', '{{date_today}}'] },
];

const workFields = (extra: TplDef['fields'] = []): TplDef['fields'] => [
  F('org_name', 'Название компании', 'Company name', 'text', { half: true, placeholderDoc: 'Manufacturas Ejemplo, S.A. de C.V.' }),
  F('head_name', 'Кому (RH/руководитель)', 'Submit to', 'text', { half: true, placeholderDoc: 'Gerencia de Recursos Humanos' }),
  F('applicant_name', 'Ваше имя', 'Your full name', 'text', { half: true, placeholderDoc: 'María Fernanda López Hernández' }),
  F('applicant_rfc', 'Ваш RFC', 'Your RFC (tax ID)', 'text', { half: true, placeholderDoc: 'RFC LOHF850101XX1' }),
  ...extra,
];

const personFields = (extra: TplDef['fields'] = []): TplDef['fields'] => [
  F('applicant_name', 'Ваше имя', 'Your full name', 'text', { half: true, placeholderDoc: 'María Fernanda López Hernández' }),
  F('applicant_rfc', 'Ваш RFC (или CURP)', 'Your RFC (or CURP)', 'text', { half: true, placeholderDoc: 'RFC LOHF850101XX1' }),
  F('applicant_address', 'Ваш адрес', 'Your address', 'text', { half: true, placeholderDoc: 'Av. Insurgentes Sur 1234, Col. Del Valle, CDMX 03100' }),
  F('applicant_phone', 'Телефон', 'Phone', 'text', { half: true, placeholderDoc: '55 1234 5678' }),
  ...extra,
];

